const get=id=>records.find(x=>x.id===id)||recurringTodos(records).find(x=>x.id===id);const listType=t=>{const saved=records.filter(r=>r.type===t&&!r.deleted);return t==='todo'?saved.concat(recurringTodos(records)):saved};
const alpha=(a,b)=>String(a.title||'').localeCompare(String(b.title||''),undefined,{sensitivity:'base'});
