const dayNumber=s=>{const m=/^(\d{4})-(\d{2})-(\d{2})$/.exec(String(s||''));return m?Date.UTC(Number(m[1]),Number(m[2])-1,Number(m[3]))/86400000:NaN};
const mixColor=(from,to,amount)=>{const a=from.match(/[\da-f]{2}/gi).map(v=>parseInt(v,16)),b=to.match(/[\da-f]{2}/gi).map(v=>parseInt(v,16));return '#'+a.map((v,i)=>Math.round(v+(b[i]-v)*amount).toString(16).padStart(2,'0')).join('')};
const TODO_GRADIENTS={warm:['#E32960','#F9732F','#FEA000'],cool:['#007DC2','#00AB6C','#8AD928']};
function todoPalette(date){const days=dayNumber(date)-dayNumber(localDate());if(Number.isFinite(days)&&days<=0)return 'urgent';return !Number.isFinite(days)||days<=60?'warm':'cool'}
function gradientPosition(index,total){if(total<=1)return 50;if(total<=11)return 50+(index-(total-1)/2)*10;if(total<=101)return index*100/(total-1);return index%101}
function gradientColor(colors,percent){return percent<=50?mixColor(colors[0],colors[1],percent/50):mixColor(colors[1],colors[2],(percent-50)/50)}
